  ctx.fillStyle = '#9a4a26'; ctx.beginPath(); ctx.ellipse(0, -560, 132, 30, 0, 0, TAU); ctx.fill(); ctx.fillStyle = '#5c3a1c'; ctx.beginPath(); ctx.ellipse(0, -560, 110, 20, 0, 0, TAU); ctx.fill();
