 // ---------- GOTITA DE AGUA ----------
 const gota = (ctx, t, x, y, r, a = 1, o = {}) => { if (a <= 0.01 || r <= 1) return; ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y + 2 * Math.sin(t * 3 + x * 0.01)); ctx.fillStyle = 'rgba(70,160,255,0.85)'; ctx.beginPath(); ctx.moveTo(0, -r * 1.5); ctx.bezierCurveTo(r * 0.5, -r * 0.8, r, -r * 0.2, r, r * 0.25); ctx.arc(0, r * 0.25, r, 0, Math.PI); ctx.bezierCurveTo(-r, -r * 0.2, -r * 0.5, -r * 0.8, 0, -r * 1.5); ctx.fill(); ctx.strokeStyle = '#d8efff'; ctx.lineWidth = Math.max(2, r * 0.08); ctx.stroke(); ctx.fillStyle = 'rgba(255,255,255,0.8)'; ctx.beginPath(); ctx.ellipse(-r * 0.35, -r * 0.1, r * 0.18, r * 0.3, 0.3, 0, TAU); ctx.fill(); ctx.restore(); };
 // ---------- BACTERIA (personaje simple, sin dar asco). o: { col, arruga, sueno, gorro, bueno, div, ang, mira, susto } ----------
 const BCOL = ['#ff7eb6', '#9b7bff', '#ff9f43', '#38c6d9', '#f45b69', '#7bd389'];
 const bacteria = (ctx, t, x, y, r, o = {}) => { const ar = o.arruga || 0, sue = o.sueno || 0, dv = o.div || 0, sd = o.seed || 0; ctx.save(); ctx.translate(x, y); ctx.rotate(o.ang || 0); const rr = r * (1 - 0.32 * ar), col = o.bueno ? '#3ccf7c' : (o.col || BCOL[sd % BCOL.length]);
  // flagelos (se mueven); quietos si duerme
  ctx.strokeStyle = col; ctx.lineWidth = Math.max(3, rr * 0.08); ctx.lineCap = 'round'; const mv = 1 - sue * 0.85; for (let k = -1; k <= 1; k++) { ctx.beginPath(); ctx.moveTo(-rr * 1.05, k * rr * 0.3); for (let i = 1; i <= 6; i++) ctx.lineTo(-rr * 1.05 - i * rr * 0.16, k * rr * 0.3 + Math.sin(i * 1.3 + t * 12 * mv + k + sd) * rr * 0.12 * mv); ctx.stroke(); }
  const cuerpo = (cx, s) => { ctx.beginPath(); if (ar > 0) { for (let i = 0; i <= 40; i++) { const a = i / 40 * TAU, rad = s * rr * (1 + 0.1 * ar * Math.sin(a * 9 + sd)); const px = cx + Math.cos(a) * rad * 1.15, py = Math.sin(a) * rad; i ? ctx.lineTo(px, py) : ctx.moveTo(px, py); } ctx.closePath(); } else ctx.ellipse(cx, 0, s * rr * 1.15, s * rr, 0, 0, TAU); };
  const dibuja = (cx, s) => { cuerpo(cx, s); ctx.fillStyle = col; ctx.fill(); if (ar > 0) { ctx.fillStyle = `rgba(80,40,30,${0.35 * ar})`; ctx.fill(); } ctx.lineWidth = Math.max(3, rr * 0.07); ctx.strokeStyle = 'rgba(40,20,40,0.35)'; ctx.stroke(); ctx.fillStyle = 'rgba(255,255,255,0.35)'; ctx.beginPath(); ctx.ellipse(cx - rr * 0.35 * s, -rr * 0.4 * s, rr * 0.3 * s, rr * 0.16 * s, -0.4, 0, TAU); ctx.fill();
   if (ar > 0.3) { ctx.strokeStyle = 'rgba(60,30,20,0.45)'; ctx.lineWidth = 3; for (let i = -1; i <= 1; i++) { ctx.beginPath(); ctx.moveTo(cx - rr * 0.6 * s, i * rr * 0.35 * s + rr * 0.3 * s); ctx.quadraticCurveTo(cx, i * rr * 0.35 * s + rr * 0.1 * s, cx + rr * 0.6 * s, i * rr * 0.35 * s + rr * 0.3 * s); ctx.stroke(); } }
   // cara
   const ey = -rr * 0.12 * s, ex = rr * 0.32 * s, er = rr * 0.2 * s * (1 + 0.5 * (o.susto || 0)), mx = (o.mira || 0) * er * 0.35; const parp = sue < 0.5 && ((t + sd * 1.3) % 3.1) < 0.12;
   for (const k of [-1, 1]) { const xx = cx + k * ex; if (sue > 0.5 || parp) { ctx.strokeStyle = '#2a1a2a'; ctx.lineWidth = Math.max(3, er * 0.35); ctx.beginPath(); ctx.arc(xx, ey, er * 0.7, 0.15, Math.PI - 0.15); ctx.stroke(); } else { ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(xx, ey, er, 0, TAU); ctx.fill(); ctx.fillStyle = '#1b1426'; ctx.beginPath(); ctx.arc(xx + mx, ey + er * 0.1, er * 0.55, 0, TAU); ctx.fill(); ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(xx + mx - er * 0.2, ey - er * 0.2, er * 0.18, 0, TAU); ctx.fill(); } }
   ctx.strokeStyle = '#2a1a2a'; ctx.lineWidth = Math.max(3, rr * 0.07); ctx.beginPath(); if (o.susto > 0.4 || ar > 0.5) { ctx.ellipse(cx, rr * 0.35 * s, rr * 0.12 * s, rr * 0.16 * s, 0, 0, TAU); ctx.stroke(); } else if (sue > 0.5) { ctx.moveTo(cx - rr * 0.12 * s, rr * 0.35 * s); ctx.lineTo(cx + rr * 0.12 * s, rr * 0.35 * s); ctx.stroke(); } else { ctx.arc(cx, rr * 0.2 * s, rr * 0.25 * s, 0.25, Math.PI - 0.25); ctx.stroke(); } };
  if (dv > 0) { const d = rr * 1.25 * E.inOut(dv), s = 1 - 0.18 * Math.sin(Math.PI * dv); dibuja(-d, s); dibuja(d, s); } else dibuja(0, 1);
  if (o.gorro) { ctx.save(); ctx.translate(rr * 0.2, -rr * 0.92); ctx.rotate(0.25 + 0.1 * Math.sin(t * 6 + sd)); ctx.fillStyle = YE; ctx.beginPath(); ctx.moveTo(-rr * 0.32, 0); ctx.lineTo(0, -rr * 0.85); ctx.lineTo(rr * 0.32, 0); ctx.closePath(); ctx.fill(); ctx.strokeStyle = RD; ctx.lineWidth = rr * 0.08; ctx.beginPath(); ctx.moveTo(-rr * 0.2, -rr * 0.25); ctx.lineTo(rr * 0.2, -rr * 0.3); ctx.moveTo(-rr * 0.1, -rr * 0.55); ctx.lineTo(rr * 0.1, -rr * 0.58); ctx.stroke(); ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(0, -rr * 0.87, rr * 0.1, 0, TAU); ctx.fill(); ctx.restore(); }
  if (sue > 0.5) { ctx.fillStyle = '#ffffff'; ctx.font = `800 ${Math.round(rr * 0.5)}px Nunito`; const zz = (t * 0.8 + sd * 0.3) % 1; ctx.globalAlpha = 1 - zz; ctx.fillText('z', rr * 0.8, -rr * (1 + zz)); ctx.globalAlpha = 1; }
  ctx.restore(); };
 // ---------- HONGO (moho: bola peluda azul verdosa con esporas) ----------
 const hongo = (ctx, t, x, y, r, o = {}) => { ctx.save(); ctx.translate(x, y); const R = RNG(o.seed || 3); ctx.strokeStyle = '#7fc8b8'; ctx.lineWidth = Math.max(3, r * 0.06); for (let i = 0; i < 7; i++) { const a = R() * TAU, L = r * (1.4 + R() * 0.6); ctx.beginPath(); ctx.moveTo(Math.cos(a) * r * 0.8, Math.sin(a) * r * 0.8); ctx.quadraticCurveTo(Math.cos(a + 0.3) * L * 0.8, Math.sin(a + 0.3) * L * 0.8, Math.cos(a) * L, Math.sin(a) * L); ctx.stroke(); ctx.fillStyle = '#a5e3d4'; ctx.beginPath(); ctx.arc(Math.cos(a) * L, Math.sin(a) * L, r * 0.16, 0, TAU); ctx.fill(); }
  ctx.fillStyle = '#4fb59e'; ctx.beginPath(); for (let i = 0; i <= 30; i++) { const a = i / 30 * TAU, rad = r * (1 + 0.08 * Math.sin(a * 12 + t * 3)); i ? ctx.lineTo(Math.cos(a) * rad, Math.sin(a) * rad) : ctx.moveTo(rad, 0); } ctx.closePath(); ctx.fill(); ctx.restore(); ctx.save(); ctx.translate(x, y);
  for (const k of [-1, 1]) { ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(k * r * 0.3, -r * 0.1, r * 0.2, 0, TAU); ctx.fill(); ctx.fillStyle = '#1b1426'; ctx.beginPath(); ctx.arc(k * r * 0.3, -r * 0.06, r * 0.11, 0, TAU); ctx.fill(); } ctx.strokeStyle = '#1b1426'; ctx.lineWidth = Math.max(3, r * 0.07); ctx.beginPath(); ctx.arc(0, r * 0.15, r * 0.25, 0.25, Math.PI - 0.25); ctx.stroke(); ctx.restore(); };
 // ---------- PARTÍCULAS DE HUMO SOBRE LA CARNE (en el microscopio) ----------
 const capaHumo = (ctx, t, R, a) => { if (a <= 0) return; const Rg = RNG(55); ctx.save(); for (let i = 0; i < 70; i++) { const x = -R + Rg() * 2 * R, y0 = -R + Rg() * 2 * R, fall = ((t * 0.12 + Rg()) % 1), y = y0 + 60 * Math.sin(t + i), r = 10 + Rg() * 18; ctx.globalAlpha = a * (0.45 + 0.35 * Rg()); ctx.fillStyle = i % 2 ? '#8a6d55' : '#b39477'; ctx.beginPath(); ctx.arc(x + 20 * Math.sin(t * 0.8 + i), y + fall * 20, r, 0, TAU); ctx.fill(); } ctx.restore(); };
 // ---------- ÁCIDO (ondas amarillo-verdosas) ----------
 const acido = (ctx, t, x, y, a, R = 300) => { if (a <= 0) return; ctx.save(); for (let i = 0; i < 4; i++) { const ph = ((t * 0.7 + i / 4) % 1); ctx.globalAlpha = a * (1 - ph) * 0.8; ctx.strokeStyle = '#d8f25a'; ctx.lineWidth = 12; ctx.beginPath(); ctx.arc(x, y, 40 + R * ph, 0, TAU); ctx.stroke(); } ctx.restore(); };
 // ---------- CARNE COLGADA EN LA CUERDA: pedazos medianos y tiras alternados, a tamaño creíble (v2). ry(x) = altura de la cuerda ----------
 const CUERDA = { x0: 80, x1: 1000, y: 960, sag: 20 };
 const ryC = (x) => { const u = (x - CUERDA.x0) / (CUERDA.x1 - CUERDA.x0); return CUERDA.y + 4 * CUERDA.sag * u * (1 - u); };
 const PIEZAS = [[260, 'p'], [375, 't'], [490, 'p'], [610, 't'], [725, 'p'], [840, 't']];
 const colgadas = (ctx, t, o = {}) => { const salta = o.salta ?? -1, seco = o.seco ?? 0.3; PIEZAS.forEach(([x, k], i) => { if (i === salta) return; const y = ryC(x), ang = 0.08 * Math.sin(t * 1.6 + i * 1.3) + 0.02 * Math.sin(t * 3.7 + i); if (k === 'p') carne(ctx, t, x, y, { s: 0.25, seco, ang }); else { ctx.save(); ctx.translate(x, y); ctx.rotate(ang); ctx.fillStyle = i % 4 === 1 ? '#7b2f24' : '#8e3a2b'; ctx.beginPath(); ctx.roundRect(-24, 4, 48, 300 + 25 * Math.sin(i * 2.3), 14); ctx.fill(); ctx.fillStyle = 'rgba(240,210,180,0.35)'; ctx.fillRect(-14, 70, 7, 170); ctx.fillStyle = '#d9c39a'; ctx.fillRect(-28, -6, 56, 16); ctx.restore(); } }); };

 // =====================================================================================================
 // ESCENAS (un plano por idea, ningún ángulo > 4 s; textos siempre encima de humo, destellos y efectos)
 // =====================================================================================================
 const B = [];
 const MC = [550, 1120];   // centro de la carne colgada en el patio
 const patio = (ctx, t, o = {}) => { cielo(ctx, t, { hz: 1300, sx: 860, sy: 1140 }); casa(ctx, t, -90, 250, 1560, { puerta: 110, top: 950 }); if (o.fogonLejos !== false) { fogon(ctx, t, 900, 1560, 0.42); humo(ctx, t, 900, 1450, { n: 9, h: 520, w: 70, r0: 16, r1: 60, a: 0.55 }); } suelo(ctx, t, 1560);
  poste(ctx, 80, 930, 1570); poste(ctx, 1000, 930, 1570); cuerda(ctx, CUERDA.x0, CUERDA.x1, CUERDA.y, CUERDA.sag); if (o.carne !== false) colgadas(ctx, t, { seco: o.seco ?? 0.3, salta: o.salta }); };
 const golpe = (k, t0, g = 1) => { k.play('thud', t0, { f: 50, gain: 0.9 * g }); k.noise(t0, { dur: 0.5, color: 'brown', filter: 'lowpass', f: [[0, 1800], [0.5, 160]], gain: 0.3 * g, a: 0.002 }); };
 const RAD = 470;   // radio del círculo del microscopio
 // bacterias repartidas (posiciones fijas por semilla) dentro de un círculo de radio R
 const grupo = (n, R, seed) => { const Rg = RNG(seed), out = []; for (let i = 0; i < n; i++) { const a = Rg() * TAU, d = Math.sqrt(Rg()) * R; out.push({ x: Math.cos(a) * d, y: Math.sin(a) * d, r: 0.8 + Rg() * 0.45, ph: Rg() * TAU, sd: i + seed }); } return out; };
 const G1 = grupo(9, 320, 3), G2 = grupo(14, 360, 7), GOT = grupo(10, 380, 11);
 const nadan = (ctx, t, g, r0, o = {}) => { for (const b of g) { const x = b.x + 30 * Math.sin(t * 0.9 + b.ph), y = b.y + 24 * Math.cos(t * 1.1 + b.ph); bacteria(ctx, t, x, y, r0 * b.r, Object.assign({ seed: b.sd, ang: 0.3 * Math.sin(t + b.ph) }, typeof o === 'function' ? o(b) : o)); } };
 const gotas = (ctx, t, g, r0, a = 1, esc = 1) => { for (const d of g) gota(ctx, t, d.x * 1.05, d.y * 1.05, r0 * d.r * esc, a); };

 // ---------- 1 · GANCHO: el patio al atardecer, la carne grande colgada se mece; las bacterias se lanzan contra ella → en «NO» chocan y rebotan (destello, sacudida, golpe) → en «pudría» el grano de sal gigante cae a cámara ----------
 const HB = (() => { const Rg = RNG(21), out = []; for (let i = 0; i < 9; i++) { const a = (i / 9) * TAU + Rg() * 0.4; out.push({ a, r: 70 + Rg() * 30, sd: i, d0: 760 + Rg() * 200 }); } return out; })();
 const ganchoBacterias = (ctx, t, TE) => { for (const b of HB) { let d; if (t < TE) d = lerp(b.d0, 360, E.in(cl(t / TE))); else d = 360 + 520 * E.out(cl((t - TE) / 0.9)); const x = MC[0] + Math.cos(b.a) * d * 1.1, y = MC[1] + Math.sin(b.a) * d * (Math.sin(b.a) < 0 ? 0.36 : 0.6), sp = t < TE ? 0 : (t - TE) * 9; bacteria(ctx, t, x, y, b.r, { seed: b.sd, ang: b.a + Math.PI + sp, susto: t > TE ? 1 : 0, mira: t < TE ? -Math.cos(b.a) : 0 }); } };
 B.push({ t0: 0, t1: S(2), in: { type: 'cut' }, draw(ctx, t) {
  if (PORTADA) { ctx.save(); zoomP(ctx, [540, 1010, 1.25]); patio(ctx, 1.2, { fogonLejos: false }); ctx.restore(); const R = 240, cx = 540, cy = 1240; ctx.save(); ctx.strokeStyle = '#3a2a1a'; ctx.lineWidth = 46; ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(cx + R * 0.72, cy + R * 0.72); ctx.lineTo(cx + R * 1.5, cy + R * 1.5); ctx.stroke(); ctx.restore(); micro(ctx, 2.0, cx, cy, R, (c) => { nadan(c, 2.0, G1, 70); gotas(c, 2.0, GOT, 26); }); ctx.fillStyle = '#2a1a12'; ctx.fillRect(0, 1790, W, HH); ctx.fillStyle = '#b8452f'; ctx.fillRect(0, 1784, W, 8); return; }
  const TE = Tk.no, TP = Tk.pudria, sh = sacude(t, [[TE, 1.3], [TP, 0.8]], 50), cam = camK(t, [[0, 540, 1160, 1.05], [S(2), 540, 1170, 1.1]]);
  ctx.save(); zoomP(ctx, cam, sh); patio(ctx, t); if (t > TE - 0.05 && t < TE + 0.5) P.glow(ctx, MC[0], MC[1], 520, '255,255,230', 0.9 * (1 - sm(TE, TE + 0.5, t))); ganchoBacterias(ctx, t, TE); ctx.restore();
  // el grano de sal cae a cámara
  if (t > TE) { const u = sm(TE, TP, t), sc = lerp(0.5, 7.2, E.in(u)) * (1 + 0.6 * sm(TP + 0.15, TP + 0.6, t)), a = 1 - sm(TP + 0.25, TP + 0.65, t); cristal(ctx, 540 + sh[0], lerp(420, 960, E.out(u)) + sh[1], sc, 0.6 + 1.2 * u, a); }
  fogonazo(ctx, t, [[TE, 0.85], [TP, 0.5]]);
  P.pregunta(ctx, '¿CÓMO LA CONSERVABAN / SIN NEVERA?', t, 0, S(2) + 0.2, { capY: 330, px: 58, clave: 'NEVERA', col: '#ff3b3b', x: 540, dy: 110 });
 }, sfx(k) { k.noise(0, { dur: S(2), filter: 'bandpass', f: 500, q: 0.6, gain: 0.05, a: 0.05 }); for (let i = 0; i < 6; i++) k.play('whoosh', 0.3 + i * 0.35, { dur: 0.3, top: 1400 + i * 200, gain: 0.12, minor: true }); golpe(k, Tk.no, 1.2); k.play('pop', Tk.no + 0.05, { f: 300, gain: 0.4 }); k.play('whoosh', Tk.no + 0.02, { dur: 0.35, top: 2600, gain: 0.3, minor: true }); golpe(k, Tk.pudria, 0.9); k.noise(Tk.pudria, { dur: 0.18, filter: 'highpass', f: 3000, gain: 0.3, a: 0.001 }); } });

 // ---------- 2 · ¿Cómo lo hacían sin nevera? → la abuela sala la carne en la mesa del patio; el niño mira asombrado; el fogón echa humo ----------
 B.push({ t0: S(2), t1: S(3), in: { type: 'cut' }, draw(ctx, t) {
  const cam = camK(t, [[S(2), 530, 1140, 1.3], [S(3), 560, 1130, 1.36]]); ctx.save(); zoomP(ctx, cam); cielo(ctx, t, { hz: 1190, sx: 860, sy: 1030 }); casa(ctx, t, -90, 420, 1450, { ventana: 200, top: 820 }); fogon(ctx, t, 900, 1450, 0.55); humo(ctx, t, 900, 1320, { n: 10, h: 600, w: 90, r0: 20, r1: 80, a: 0.6 }); suelo(ctx, t, 1450);
  const sal = 0.5 + 0.5 * Math.sin((t - S(2)) * 6); persona(ctx, t, 640, 1450, 1.05, { abuela: true, ropa: '#7a4f9a', sonrie: 0.6, brazoI: [-170, -300 - 20 * sal], brazoD: [60, -250], seed: 1, mira: -1 });
  mesa(ctx, 230, 860, 1240, { patas: 210 }); ctx.save(); ctx.translate(500, 1205); ctx.rotate(-0.04); ctx.fillStyle = '#c8935e'; ctx.fillRect(-230, -16, 460, 24); ctx.restore(); ctx.save(); ctx.translate(500, 1196); ctx.scale(0.55, 0.2); carne(ctx, 0, 0, -380, { ang: 0, seco: 0.1, sinGancho: true }); ctx.restore();
  const R = RNG(5); for (let i = 0; i < 14; i++) { const ph = ((t * 1.6 + R()) % 1), hx = 640 + 1.05 * -170 + R() * 30, hy = 1450 + 1.05 * (-300) + 10; cristal(ctx, hx - 20 + 40 * R(), lerp(hy, 1195, ph), 0.08 + 0.04 * R(), R() * 3, 1 - ph * 0.3); }
  persona(ctx, t, 270, 1450, 0.62, { ropa: '#f2b632', miedo: 0.55, mira: 1, seed: 4, pelo: '#3b2414' }); ctx.restore();
 }, sfx(k) { for (let x = S(2) + 0.1; x < S(3); x += 0.18) k.play('tick', x, { f: 3000, gain: 0.05, minor: true }); k.noise(S(2), { dur: S(3) - S(2), color: 'brown', filter: 'lowpass', f: 600, gain: 0.08, a: 0.1 }); } });

 // ---------- 3 · El secreto es el mismo en todas las técnicas. → la cámara se acerca a la carne y se abre el círculo del microscopio → dentro, las bacterias y las gotitas; la cámara gira ----------
 B.push({ t0: S(3), t1: S(4), in: { type: 'cut' }, draw(ctx, t) {
  const tb = S(3) + 0.25, R = RAD * E.out(sm(tb, tb + 0.9, t)), cam = camK(t, [[S(3), 520, 1110, 1.4], [tb + 0.9, 490, 1075, 2.6]]);
  if (R < RAD - 1) { ctx.save(); zoomP(ctx, cam); patio(ctx, t); ctx.restore(); }
  else fondoMicro(ctx);
  if (R > 2) micro(ctx, t, 540, 980, R, (c) => { gotas(c, t, GOT, 30); nadan(c, t, G1, 64); }, { giro: 0.25 * sm(S(3) + 1.6, S(4), t), zoom: lerp(1, 1.25, sm(S(3) + 1.6, S(4), t)) });
  TAG(ctx, 'EL MISMO SECRETO', 470, 520, t, Tk.mismo - 0.3, S(4), { mono: true, col: YE, px: 56 });
 }, sfx(k) { k.play('whoosh', S(3) + 0.2, { dur: 0.9, top: 2000, gain: 0.3 }); FX.revelar(k, S(3) + 0.6); FX.etiqueta(k, Tk.mismo - 0.3); k.noise(S(3) + 1, { dur: 2.2, filter: 'bandpass', f: 1200, q: 2, gain: 0.03, a: 0.3 }); } });

 // ---------- 4 · La comida se daña por bichos invisibles: → al microscopio se multiplican sin parar → bacterias y hongos: el ejército carga contra la cámara ----------
 const ARMY = (() => { const Rg = RNG(61), out = []; for (let i = 0; i < 26; i++) out.push({ x: (Rg() - 0.5) * 1500, y: (Rg() - 0.5) * 1100, z0: 1 + Rg() * 5, sd: i }); return out; })();
 B.push({ t0: S(4), t1: S(6), in: { type: 'cut' }, draw(ctx, t) {
  const tb = Tk.invisibles - 0.15;
  if (t < tb) { fondoMicro(ctx); const u = sm(S(4), tb, t), n = Math.min(G2.length, 3 + Math.floor(u * 12)); micro(ctx, t, 540, 980, RAD, (c) => { for (let i = 0; i < n; i++) { const b = G2[i], dv = ((t * 1.2 + b.ph) % 1.6) / 1.6; bacteria(c, t, b.x + 20 * Math.sin(t + b.ph), b.y, 60 * b.r, { seed: b.sd, div: dv < 0.7 ? dv / 0.7 : 0 }); } gotas(c, t, GOT, 24, 1 - u * 0.3); }, { zoom: lerp(1.0, 1.15, u), giro: -0.15 * u }); TAG(ctx, 'SE DAÑA', 470, 520, t, Tk.daña - 0.2, tb, { mono: true, col: RD, px: 60 }); }
  else { const sh = sacude(t, [[Tk.bacterias, 0.6]], 30); fondoMicro(ctx); ctx.save(); ctx.translate(sh[0], sh[1]); ctx.save(); ctx.beginPath(); ctx.arc(540, 980, 600, 0, TAU); ctx.clip(); ctx.translate(540, 980); microFondo(ctx, t, 900); ctx.restore();
   const vv = 1.6, lst = ARMY.map((b) => { let z = b.z0 - (t - tb) * vv; z = ((z - 0.35) % 6 + 6) % 6 + 0.35; return Object.assign({ z }, b); }).sort((a, b) => b.z - a.z);
   for (const b of lst) { const s = 1 / b.z, x = 540 + b.x * s, y = 980 + b.y * s, r = 120 * s; if (r > 900) continue; ctx.save(); ctx.globalAlpha = cl((6 - b.z) / 1.5); if (b.sd % 5 === 4) hongo(ctx, t, x, y, r * 0.9, { seed: b.sd }); else bacteria(ctx, t, x, y, r, { seed: b.sd, mira: 0, ang: 0.2 * Math.sin(t * 3 + b.sd) }); ctx.restore(); }
   if (t > Tk.hongos - 0.3) { const a = sm(Tk.hongos - 0.3, Tk.hongos, t); ctx.save(); ctx.globalAlpha = a; hongo(ctx, t, 540, 1000, 190 * (0.6 + 0.4 * a), { seed: 2 }); ctx.restore(); }
   ctx.restore(); TAG(ctx, 'BACTERIAS', 470, 520, t, Tk.bacterias - 0.2, Tk.hongos - 0.35, { mono: true, col: '#ff7eb6', px: 64 }); TAG(ctx, 'HONGOS', 470, 520, t, Tk.hongos - 0.2, S(6), { mono: true, col: '#7fe0c8', px: 64 }); }
 }, sfx(k) { for (let x = S(4) + 0.2; x < Tk.invisibles; x += 0.22) k.play('pop', x, { f: 700 + 100 * Math.sin(x * 9), gain: 0.12, minor: true }); FX.etiqueta(k, Tk.daña - 0.2); k.play('whoosh', Tk.invisibles - 0.15, { dur: 0.6, top: 1800, gain: 0.35 }); k.noise(Tk.invisibles, { dur: S(6) - Tk.invisibles, color: 'brown', filter: 'lowpass', f: [[0, 300], [2.5, 900]], gain: 0.12, a: 0.2 }); golpe(k, Tk.bacterias, 0.6); FX.etiqueta(k, Tk.bacterias - 0.2); FX.etiqueta(k, Tk.hongos - 0.2); k.play('pop', Tk.hongos, { f: 250, gain: 0.35 }); } });

 // ---------- 5 · Son como invitados colados en una fiesta… → bacterias con gorro de fiesta que bailan, confeti y luces → para quedarse necesitan AGUA (beben de las gotitas) y estar CÓMODOS (luz cálida, se dividen) ----------
 const confeti = (ctx, t, R, a = 1) => { const Rg = RNG(71); ctx.save(); ctx.globalAlpha = a; for (let i = 0; i < 60; i++) { const x = -R + Rg() * 2 * R, sp = 120 + Rg() * 160, y = ((Rg() * 2 * R + t * sp) % (2 * R)) - R, c = BCOL[i % BCOL.length]; ctx.save(); ctx.translate(x + 20 * Math.sin(t * 3 + i), y); ctx.rotate(t * 4 + i); ctx.fillStyle = c; ctx.fillRect(-9, -5, 18, 10); ctx.restore(); } ctx.restore(); };
 const luces = (ctx, t, R, a = 1) => { ctx.save(); ctx.globalAlpha = 0.28 * a; for (let i = 0; i < 3; i++) { const an = t * (0.9 + i * 0.4) + i * 2; ctx.fillStyle = ['#ff4fd8', '#4fd1ff', '#ffe14f'][i]; ctx.beginPath(); ctx.moveTo(0, -R); ctx.lineTo(Math.cos(an) * R * 1.4 - 120, Math.sin(an) * R * 1.4); ctx.lineTo(Math.cos(an) * R * 1.4 + 120, Math.sin(an) * R * 1.4); ctx.closePath(); ctx.fill(); } ctx.restore(); };
 B.push({ t0: S(6), t1: S(8), in: { type: 'cut' }, draw(ctx, t) {
  const t1 = S(7) - 0.05, t2 = Tk.agua - 0.3; fondoMicro(ctx);
  if (t < t1) { micro(ctx, t, 540, 980, RAD, (c) => { luces(c, t, RAD); gotas(c, t, GOT, 26); for (const b of G1) { const salto = Math.abs(Math.sin(t * 6 + b.ph)) * 30; bacteria(c, t, b.x, b.y - salto, 66 * b.r, { seed: b.sd, gorro: true, ang: 0.25 * Math.sin(t * 6 + b.ph) }); } confeti(c, t, RAD); }, { giro: 0.3 * Math.sin((t - S(6)) * 0.6), zoom: 1.05 }); TAG(ctx, 'INVITADOS COLADOS', 470, 520, t, Tk.invitados - 0.3, t1, { mono: true, col: YE, px: 54 }); }
  else if (t < t2) { const u = sm(t1, t2, t); micro(ctx, t, 540, 980, RAD, (c) => { const sorbo = 0.5 + 0.5 * Math.sin(t * 7); gota(c, t, 90, 40, 150 * (1 - 0.35 * u), 1); c.strokeStyle = '#fff'; c.lineWidth = 12; c.beginPath(); c.moveTo(-60, 0); c.lineTo(40, -30 - 6 * sorbo); c.stroke(); bacteria(c, t, -170, 30, 140 * (1 + 0.1 * u), { seed: 1, gorro: true, ang: -0.2 }); }, { zoom: lerp(1.0, 1.15, u) }); }
  else { const u = sm(t2, S(8), t); micro(ctx, t, 540, 980, RAD, (c) => { if (t > Tk.comodos - 0.4) { P.glow(c, 0, 0, RAD * 1.2, '255,170,60', 0.45 * sm(Tk.comodos - 0.4, Tk.comodos, t)); } gotas(c, t, GOT, 30); for (const b of G2.slice(0, 10)) { const dv = ((t - t2) * 0.8 + b.ph / TAU) % 1; bacteria(c, t, b.x, b.y, 58 * b.r, { seed: b.sd, gorro: true, div: dv < 0.75 ? dv / 0.75 : 0 }); } }, { giro: -0.2 * u, zoom: lerp(1.15, 1.0, u) });
   TAG(ctx, 'AGUA', 470, 520, t, Tk.agua - 0.2, Tk.comodos - 0.35, { mono: true, col: AZ, px: 72 }); TAG(ctx, 'Y ESTAR CÓMODOS', 470, 520, t, Tk.comodos - 0.2, S(8), { mono: true, col: NAR, px: 58 }); }
 }, sfx(k) { const t1 = S(7) - 0.05; for (let x = S(6); x < t1; x += 60 / 118) { k.play('tick', x, { f: 1800, gain: 0.08, minor: true }); k.tone(x, { f: 65, type: 'sine', dur: 0.12, gain: 0.12 }); } FX.etiqueta(k, Tk.invitados - 0.3); k.play('sparkle', S(6) + 0.1, { gain: 0.2 }); for (let x = t1 + 0.1; x < Tk.agua - 0.3; x += 0.32) k.play('blip', x, { f: 500, gain: 0.08, minor: true }); FX.etiqueta(k, Tk.agua - 0.2); FX.etiqueta(k, Tk.comodos - 0.2); for (let x = Tk.agua; x < S(8); x += 0.4) k.play('pop', x, { f: 900, gain: 0.08, minor: true }); } });

 // ---------- 6 · Cada truco de la abuela les arruina la fiesta. → en el patio la abuela cuelga la carne y el niño la ayuda → en «arruina» la fiesta del microscopio se apaga: se caen los gorros ----------
 B.push({ t0: S(8), t1: S(9), in: { type: 'cut' }, draw(ctx, t) {
  const tb = Tk.arruina - 0.1;
  if (t < tb) { const cam = camK(t, [[S(8), 560, 1130, 1.0], [tb, 540, 1110, 1.06]]), lev = Math.sin((t - S(8)) * 2.5); ctx.save(); zoomP(ctx, cam); patio(ctx, t, { salta: 4 }); persona(ctx, t, 925, 1570, 1.05, { abuela: true, ropa: '#7a4f9a', sonrie: 0.8, brazoI: [-90, -560 + 14 * lev], brazoD: [-50, -570 - 14 * lev], seed: 2, mira: -1 }); persona(ctx, t, 230, 1570, 0.7, { ropa: '#f2b632', sonrie: 1, salto: 0.2 * Math.max(0, Math.sin((t - S(8)) * 7)), brazoD: [110, -620], seed: 5, pelo: '#3b2414', mira: 1 }); ctx.restore(); }
  else { const u = sm(tb, tb + 0.5, t); fondoMicro(ctx); micro(ctx, t, 540, 980, RAD, (c) => { luces(c, t, RAD, 1 - u); c.fillStyle = `rgba(10,10,30,${0.45 * u})`; c.fillRect(-RAD * 2, -RAD * 2, RAD * 4, RAD * 4); for (const b of G1) { bacteria(c, t, b.x, b.y + 20 * u, 66 * b.r, { seed: b.sd, susto: u, gorro: false, mira: Math.sin(t * 5 + b.ph) }); const gy = lerp(b.y - 66 * b.r, b.y + 260, E.in(u)); c.save(); c.globalAlpha = 1 - sm(tb + 0.5, tb + 1, t); c.translate(b.x + 30 * u, gy); c.rotate(2 * u + b.ph); c.fillStyle = YE; c.beginPath(); c.moveTo(-20, 0); c.lineTo(0, -52); c.lineTo(20, 0); c.closePath(); c.fill(); c.restore(); } }, { zoom: 1.08 }); }
 }, sfx(k) { k.noise(S(8), { dur: Tk.arruina - S(8), color: 'pink', filter: 'lowpass', f: 900, gain: 0.05, a: 0.2 }); k.tone(Tk.arruina - 0.1, { f: [[0, 600], [0.5, 90]], type: 'sawtooth', dur: 0.55, gain: 0.08, filter: 'lowpass', f2: 1500 }); k.play('error', Tk.arruina, { gain: 0.25 }); } });

 // ---------- 7 · LA SAL… les saca el agua, y se arrugan como pasas. → primer plano: la mano echa sal sobre la carne → al microscopio, la sal saca el agua de las bacterias, que se arrugan en cámara lenta → plano abierto de bacterias arrugadas ----------
 B.push({ t0: S(9), t1: S(10), in: { type: 'cut' }, draw(ctx, t) {
  const t1 = Tk.saca + 0.4, t2 = Tk.pasas - 0.25;
  if (t < t1) { const cam = camK(t, [[S(9), 540, 1000, 1.0], [t1, 540, 1020, 1.08]]); ctx.save(); zoomP(ctx, cam); ctx.fillStyle = '#7a4a2a'; ctx.fillRect(-300, -300, W + 600, HH + 600); ctx.fillStyle = '#9c6239'; for (let i = 0; i < 8; i++) ctx.fillRect(-300, 300 + i * 220, W + 600, 8);
   carne(ctx, 0, 540, 470, { ang: -0.05, seco: 0.05, s: 1.45, sinGancho: true });
   const R = RNG(8); for (let i = 0; i < 26; i++) { const ph = ((t - S(9)) * 1.3 + R()) % 1.2, x = 600 + (R() - 0.5) * 260 + ph * 60 * (R() - 0.5), y = lerp(560, 1000 + R() * 260, Math.min(1, ph)); cristal(ctx, x, y, 0.2 + 0.15 * R(), R() * 6 + t, 1); }
   for (let i = 0; i < 18; i++) { const x = 330 + (i * 47) % 460, y = 960 + ((i * 89) % 300); cristal(ctx, x, y, 0.16, i, 1); }
   if (typeof window !== 'undefined' && window.MANOS_IMG) P.manoImg(ctx, 'pinza', 640 + 10 * Math.sin(t * 9), 520 + 8 * Math.sin(t * 7), 360, { ancla: 'centro', ang: 2.6 }); ctx.restore(); TAG(ctx, '1 · LA SAL', 470, 520, t, Tk.sal - 0.2, t1 + 0.25, { mono: true, col: '#ffffff', px: 66 }); }
  else if (t < t2) { const u = sm(Tk.arrugan - 0.4, t2, t); fondoMicro(ctx); micro(ctx, t, 540, 980, RAD, (c) => { for (let i = 0; i < 6; i++) { const a = i * TAU / 6 + 0.3; cristal(c, Math.cos(a) * 330, Math.sin(a) * 330, 1.1, a, 1); } bacteria(c, t, 0, 0, 170, { seed: 2, arruga: u, susto: u }); for (let i = 0; i < 6; i++) { const a = i * TAU / 6 + 0.3, ph = ((t * 0.7 + i / 6) % 1), d = lerp(140, 300, ph); gota(c, t, Math.cos(a) * d, Math.sin(a) * d, 26 * (1 - ph * 0.5), 1 - ph); } }, { zoom: lerp(1.25, 1.1, sm(t1, t2, t)), giro: 0.2 * sm(t1, t2, t) }); TAG(ctx, 'LES SACA EL AGUA', 470, 520, t, t1, Tk.arrugan - 0.25, { mono: true, col: AZ, px: 56 }); TAG(ctx, 'SE ARRUGAN', 470, 520, t, Tk.arrugan - 0.2, t2 + 0.25, { mono: true, col: '#ffffff', px: 60 }); }
  else { fondoMicro(ctx); const sh = sacude(t, [[Tk.pasas, 0.5]], 26); micro(ctx, t, 540 + sh[0], 980 + sh[1], RAD, (c) => { const Rg = RNG(14); for (let i = 0; i < 18; i++) cristal(c, (Rg() - 0.5) * 820, (Rg() - 0.5) * 820, 0.5, Rg() * 6, 1); nadan(c, t, G2.slice(0, 9), 70, { arruga: 1, susto: 0.6 }); }, { giro: -0.2 * sm(t2, S(10), t), zoom: 0.95 }); TAG(ctx, 'COMO PASAS', 470, 520, t, Tk.pasas + 0.05, S(10), { mono: true, col: '#c08a5a', px: 60 }); }
 }, sfx(k) { FX.clave(k, Tk.sal - 0.2); for (let x = S(9) + 0.1; x < Tk.saca + 0.4; x += 0.06) k.noise(x, { dur: 0.03, filter: 'highpass', f: 5000, gain: 0.06, a: 0.001 }); FX.etiqueta(k, Tk.saca + 0.4); k.tone(Tk.arrugan - 0.4, { f: [[0, 500], [1.2, 150]], type: 'sine', dur: 1.3, gain: 0.08 }); FX.etiqueta(k, Tk.arrugan - 0.2); golpe(k, Tk.pasas, 0.5); FX.etiqueta(k, Tk.pasas - 0.2); } });

 // ---------- 8 · EL SOL Y EL VIENTO secan la carne, como el CHARQUI de los Andes. Sin agua, no hay fiesta. → sol grande y tiras de carne que se mecen con el viento → los Andes con el charqui colgado → al microscopio las gotitas se evaporan ----------
